export function scrubPayload(payload: Record<string, unknown>): Record<string, unknown> {
  const scrubbed: Record<string, unknown> = { ...payload };
  for (const key of Object.keys(scrubbed)) {
    if (PAYLOAD_PII_KEYS.has(key)) scrubbed[key] = null;
  }
  for (const nestedKey of ['customerSnapshot', 'customer'] as const) {
    const nested = scrubbed[nestedKey];
    if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
      const nestedId = (nested as Record<string, unknown>).id;
      const fallbackId = scrubbed.customerId;
      scrubbed[nestedKey] = scrubbedCustomerIdentity(
        typeof nestedId === 'string' ? nestedId : typeof fallbackId === 'string' ? fallbackId : '',
      );
    }
  }
  return scrubbed;
}
