{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';
import { ERASED_LABEL, scrubPayload } from '../../../packages/privacy/src/scrub.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  idempotency_key: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  available_at: Date;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export class ErasureRepository {
  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByKey(client: pg.PoolClient, merchantId: string, key: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2 FOR UPDATE`,
      [merchantId, key],
    );
    return result.rows[0];
  }

  async findByCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async create(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    key: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3) ON CONFLICT DO NOTHING RETURNING *`,
      [merchantId, customerId, key],
    );
    return result.rows[0];
  }

  /** A failed request is safe to retry: requeue it without losing the request id or finished work. */
  async requeueIfFailed(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='pending',available_at=now(),updated_at=now()
       WHERE id=$1 AND status='failed'`,
      [requestId],
    );
  }

  /** Atomically claims the next runnable request and stops new activity on the customer. */
  async claim(): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,last_error=NULL,updated_at=now()
       WHERE id=(SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed') AND available_at<=now()
         ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING *`,
    );
    const request = result.rows[0];
    if (request) {
      await pool.query(
        `UPDATE customers.customers SET status='erasing',updated_at=now()
         WHERE merchant_id=$1 AND id=$2 AND status='active'`,
        [request.merchant_id, request.customer_id],
      );
    }
    return request;
  }

  /** Returns requests whose worker disappeared mid-attempt back to the runnable set. */
  async recoverStaleProcessing(staleSeconds = 60): Promise<number> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status='pending',available_at=now(),updated_at=now()
       WHERE status='processing' AND updated_at<now()-($1 || ' seconds')::interval`,
      [staleSeconds],
    );
    return result.rowCount ?? 0;
  }

  async markCompleted(requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL
       WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(requestId: string, code: string, retryDelaySeconds: number): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',last_error=$2,available_at=now()+($3 || ' seconds')::interval,updated_at=now()
       WHERE id=$1`,
      [requestId, code, retryDelaySeconds],
    );
  }

  /**
   * Removes or anonymizes the customer's personal data in relational records while
   * keeping retained financial records (payments, invoices, ledger) financially correct.
   * Every statement is idempotent so a resumed request converges on the same result.
   */
  async scrubCustomerRecords(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    const scoped = [merchantId, customerId];
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(
      `DELETE FROM customers.support_participants
       WHERE customer_id=$2 AND ticket_id IN (SELECT id FROM customers.support_tickets WHERE merchant_id=$1)`,
      scoped,
    );
    await client.query(
      `UPDATE customers.support_messages SET body=$3,author_id=NULL,attachments='[]'
       WHERE merchant_id=$1 AND author_type='customer' AND author_id=$2`,
      [merchantId, customerId, ERASED_LABEL],
    );
    await client.query(
      `UPDATE customers.customers
       SET email='erased-' || id::text || '@erased.invalid',name=$3,phone=NULL,
           external_reference='erased-' || id::text,metadata='{}',status='erased',
           version=version+1,updated_at=now()
       WHERE merchant_id=$1 AND id=$2 AND status<>'erased'`,
      [merchantId, customerId, ERASED_LABEL],
    );
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email='erased-' || $2::text || '@erased.invalid',name=$3,external_reference='erased-' || $2::text,updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId, ERASED_LABEL],
    );
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_build_object('id',$2::text,'status','erased'),description=NULL,updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2 AND customer_snapshot->>'status' IS DISTINCT FROM 'erased'`,
      scoped,
    );
    await client.query(
      `UPDATE payments.payment_attempts
       SET request_payload=request_payload-'description'
       WHERE merchant_id=$1 AND request_payload?'description'
         AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      scoped,
    );
    await client.query(
      `UPDATE payments.refunds SET customer_email=NULL
       WHERE merchant_id=$1 AND customer_email IS NOT NULL
         AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      scoped,
    );
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=jsonb_build_object('id',$2::text,'status','erased')
       WHERE merchant_id=$1 AND customer_id=$2 AND billing_snapshot->>'status' IS DISTINCT FROM 'erased'`,
      scoped,
    );
    await client.query(`DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(`DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`, scoped);
    await client.query(
      `UPDATE platform.audit_logs SET metadata='{}'
       WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2`,
      scoped,
    );
    await this.scrubStoredPayloads(client, merchantId, customerId);
  }

  /** Rewrites queued and historical payloads so delayed work cannot re-emit personal data. */
  private async scrubStoredPayloads(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    const outbox = await client.query<{ id: string; payload: Record<string, unknown> }>(
      `SELECT id,payload FROM operations.outbox_events
       WHERE merchant_id=$1 AND (payload->>'customerId'=$2 OR (aggregate_type='customer' AND aggregate_id=$2::uuid))`,
      [merchantId, customerId],
    );
    for (const row of outbox.rows) {
      await client.query(`UPDATE operations.outbox_events SET payload=$2 WHERE id=$1`, [row.id, scrubPayload(row.payload)]);
    }
    const jobs = await client.query<{ id: string; payload: Record<string, unknown> }>(
      `SELECT id,payload FROM operations.jobs WHERE merchant_id=$1 AND payload->>'customerId'=$2`,
      [merchantId, customerId],
    );
    for (const row of jobs.rows) {
      await client.query(`UPDATE operations.jobs SET payload=$2 WHERE id=$1`, [row.id, scrubPayload(row.payload)]);
    }
    const deadLetters = await client.query<{ id: string; payload: Record<string, unknown> }>(
      `SELECT id,payload FROM operations.dead_letters
       WHERE payload->>'merchantId'=$1 AND payload->>'customerId'=$2`,
      [merchantId, customerId],
    );
    for (const row of deadLetters.rows) {
      await client.query(`UPDATE operations.dead_letters SET payload=$2 WHERE id=$1`, [row.id, scrubPayload(row.payload)]);
    }
  }

  /** Lists stored documents that embed the customer's data and must be rewritten. */
  async listCustomerDocuments(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<{ invoices: string[]; receipts: string[]; imports: string[] }> {
    const invoices = await client.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type='invoice'`,
      [merchantId, customerId],
    );
    const receipts = await client.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND document_type='receipt'
         AND metadata->>'paymentId' IN (
           SELECT id::text FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
    const imports = await client.query<{ object_key: string }>(
      `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1`,
      [merchantId],
    );
    return {
      invoices: invoices.rows.map((row) => row.object_key),
      receipts: receipts.rows.map((row) => row.object_key),
      imports: imports.rows.map((row) => row.object_key),
    };
  }

  async updateManifestChecksum(merchantId: string, objectKey: string, checksum: string): Promise<void> {
    await pool.query(
      `UPDATE operations.document_manifests SET checksum=$3 WHERE merchant_id=$1 AND object_key=$2`,
      [merchantId, objectKey, checksum],
    );
  }

  async deleteManifest(merchantId: string, objectKey: string): Promise<void> {
    await pool.query(
      `DELETE FROM operations.document_manifests WHERE merchant_id=$1 AND object_key=$2`,
      [merchantId, objectKey],
    );
  }
}
"}

{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { createHash } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { scrubPayload, scrubbedCustomerIdentity } from '../../../packages/privacy/src/scrub.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';
import { CustomerRepository } from './repository.js';

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: string;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function toResponse(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

/** Stable failure codes exposed as lastError. They never contain customer data. */
class CleanupError extends Error {
  constructor(readonly code: string, cause: unknown) {
    super(cause instanceof Error ? cause.message : String(cause));
  }
}

const redis = new Redis(config().REDIS_URL);

export class ErasureService {
  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly customers = new CustomerRepository(),
  ) {}

  async request(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: Record<string, unknown> }> {
    const customer = await this.customers.find(merchantId, customerId);
    if (!customer) return { status: 404, body: { error: 'customer_not_found' } };
    return transaction(async (client) => {
      const byKey = await this.repository.findByKey(client, merchantId, idempotencyKey);
      if (byKey && byKey.customer_id !== customerId) {
        throw Object.assign(new Error('idempotency key already used for a different customer'), { statusCode: 409 });
      }
      const existing = byKey ?? await this.repository.findByCustomer(client, merchantId, customerId);
      if (existing) {
        await this.repository.requeueIfFailed(client, existing.id);
        const current = await this.repository.findByCustomer(client, merchantId, customerId);
        return { status: 202, body: toResponse(current ?? existing) as unknown as Record<string, unknown> };
      }
      const created = await this.repository.create(client, merchantId, customerId, idempotencyKey);
      if (created) return { status: 202, body: toResponse(created) as unknown as Record<string, unknown> };
      // A concurrent request won the insert race; return the winning request.
      const winner = await this.repository.findByKey(client, merchantId, idempotencyKey)
        ?? await this.repository.findByCustomer(client, merchantId, customerId);
      if (!winner) throw new Error('erasure request could not be created');
      if (winner.customer_id !== customerId) {
        throw Object.assign(new Error('idempotency key already used for a different customer'), { statusCode: 409 });
      }
      return { status: 202, body: toResponse(winner) as unknown as Record<string, unknown> };
    });
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestResponse | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? toResponse(row) : undefined;
  }

  /**
   * Runs the full cleanup for a claimed request. Every step is idempotent, so a
   * failed or interrupted attempt can resume safely and converges on the same result.
   */
  async runCleanup(request: ErasureRequestRow): Promise<void> {
    const merchantId = request.merchant_id;
    const customerId = request.customer_id;
    let documents: { invoices: string[]; receipts: string[]; imports: string[] };
    try {
      documents = await transaction(async (client) => {
        await this.repository.scrubCustomerRecords(client, merchantId, customerId);
        return await this.repository.listCustomerDocuments(client, merchantId, customerId);
      });
    } catch (error) {
      throw new CleanupError('database_cleanup_failed', error);
    }
    try {
      for (const objectKey of [...documents.invoices, ...documents.receipts]) {
        await this.rewriteStoredDocument(merchantId, objectKey, customerId);
      }
      for (const objectKey of documents.imports) {
        await this.deleteImportIfCustomerData(merchantId, objectKey, customerId);
      }
    } catch (error) {
      throw new CleanupError('storage_cleanup_failed', error);
    }
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` });
    } catch (error) {
      if ((error as { meta?: { statusCode?: number } }).meta?.statusCode !== 404) {
        throw new CleanupError('search_cleanup_failed', error);
      }
    }
    try {
      const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
      await redis.del(cacheKey, `${cacheKey}:activity`);
    } catch (error) {
      throw new CleanupError('cache_cleanup_failed', error);
    }
  }

  /** Rewrites a retained financial document so it keeps its meaning without identifying the customer. */
  private async rewriteStoredDocument(merchantId: string, objectKey: string, customerId: string): Promise<void> {
    const content = await this.readObject(objectKey);
    if (content === undefined) return;
    const parsed = JSON.parse(content) as Record<string, unknown>;
    const scrubbed = scrubPayload({ ...parsed, customer: scrubbedCustomerIdentity(customerId) });
    const body = JSON.stringify(scrubbed);
    await objectStore.putObject(DOCUMENT_BUCKET, objectKey, body, Buffer.byteLength(body), {
      'Content-Type': 'application/json',
    });
    await this.repository.updateManifestChecksum(
      merchantId, objectKey, createHash('sha256').update(body).digest('hex'),
    );
  }

  /** Removes raw import artifacts that contain the erased customer's record. */
  private async deleteImportIfCustomerData(merchantId: string, objectKey: string, customerId: string): Promise<void> {
    const content = await this.readObject(objectKey);
    if (content === undefined) {
      await this.repository.deleteManifest(merchantId, objectKey);
      return;
    }
    if (!content.includes(customerId)) return;
    await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
    await this.repository.deleteManifest(merchantId, objectKey);
  }

  private async readObject(objectKey: string): Promise<string | undefined> {
    try {
      const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
      const chunks: Buffer[] = [];
      for await (const chunk of stream) chunks.push(chunk as Buffer);
      return Buffer.concat(chunks).toString('utf8');
    } catch (error) {
      const code = (error as { code?: string }).code;
      if (code === 'NoSuchKey' || code === 'NotFound') return undefined;
      throw error;
    }
  }
}
"}

{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-worker.ts","file_text":"import { logger } from '../../../packages/observability/src/logger.js';
import { boundedExponentialBackoffSeconds } from '../../../packages/operations/src/retry-policy.js';
import { ErasureRepository } from './erasure-repository.js';
import { ErasureService } from './erasure-service.js';

const repository = new ErasureRepository();
const service = new ErasureService();

/** Polls for data deletion requests and runs their cleanup until completion. */
export async function startErasureWorker(signal: AbortSignal): Promise<void> {
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    try {
      if (Date.now() - lastLeaseRecovery > 30_000) {
        await repository.recoverStaleProcessing();
        lastLeaseRecovery = Date.now();
      }
      const request = await repository.claim();
      if (!request) {
        await new Promise((resolve) => setTimeout(resolve, 250));
        continue;
      }
      try {
        await service.runCleanup(request);
        await repository.markCompleted(request.id);
        logger.info({ requestId: request.id }, 'erasure request completed');
      } catch (error) {
        const code = typeof (error as { code?: unknown }).code === 'string'
          ? (error as { code: string }).code
          : 'cleanup_failed';
        logger.error({ error, requestId: request.id }, 'erasure request attempt failed');
        await repository.markFailed(request.id, code, boundedExponentialBackoffSeconds(request.attempts));
      }
    } catch (error) {
      logger.error({ error }, 'erasure worker iteration failed');
      await new Promise((resolve) => setTimeout(resolve, 1_000));
    }
  }
}
"}

