async function removeProjection(merchantId: string, customerId: string): Promise<void> {
  const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
  await redis.del(cacheKey, `${cacheKey}:activity`);
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` });
  } catch (error) {
    if ((error as { meta?: { statusCode?: number } }).meta?.statusCode !== 404) throw error;
  }
}

async function handle({ message, partition }: EachMessagePayload): Promise<void> {
  if (!message.value) return;
  const event = eventEnvelopeSchema.parse(JSON.parse(message.value.toString()));
  if (!await repository.claim(event)) return;
  const customerId = typeof event.payload.customerId === 'string'
    ? event.payload.customerId
    : event.aggregateType === 'customer' ? event.aggregateId : undefined;
  try {
    if (customerId && await isCustomerErased(event.merchantId, customerId)) {
      // Delayed or replayed events must never restore deleted personal data.
      await removeProjection(event.merchantId, customerId);
      await repository.complete({ ...event, payload: scrubPayload(event.payload) }, undefined, partition, Number(message.offset));
      return;
    }
    await project(event);
    await repository.complete(event, customerId, partition, Number(message.offset));
  } catch (error) {
    await repository.fail(event.eventId, error);
    throw error;
  }
}"}

