      // Existing requests are found first so reposting stays valid after the customer is gone.
      const byKey = await this.repository.findByKey(client, merchantId, idempotencyKey);
      if (byKey && byKey.customer_id !== customerId) {
        throw Object.assign(new Error('idempotency key already used for a different customer'), { statusCode: 409 });
