      const existing = byKey ?? await this.repository.findByCustomer(client, merchantId, customerId);
      if (existing) {
        await this.repository.requeueIfFailed(client, existing.id);
        const current = byKey
          ? await this.repository.findByKey(client, merchantId, idempotencyKey)
          : await this.repository.findByCustomer(client, merchantId, customerId);
