      const winner = await this.repository.findByKey(client, merchantId, idempotencyKey)
        ?? await this.repository.findByCustomer(client, merchantId, customerId);
      if (!winner) throw new Error('erasure request could not be created');
      if (winner.customer_id !== customerId) {
