{"command":"create","path":"/workspace/source/scripts/tmp-erasure-e2e.ts","file_text":"/* Temporary end-to-end verification for customer data deletion. Deleted after use. */
import assert from 'node:assert/strict';
import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { pool } from '../packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../packages/storage/src/minio.js';

const gateway = process.env.GATEWAY_URL ?? 'http://api-gateway:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';
const otherKey = 'pf_local_dev_bluebird_924bd90d2201';
const restrictedKey = 'pf_restricted_no_privacy_scope';
const merchantId = '10000000-0000-4000-8000-000000000001';
const suffix = randomUUID().slice(0, 8);

const PII = {
  email: `erase-target-${suffix}@example.test`,
  name: `Erika Erasure ${suffix}`,
  phone: `+1-555-01${suffix.slice(0, 4)}`,
  externalReference: `crm-erase-${suffix}`,
};
const CONTROL = {
  email: `control-${suffix}@example.test`,
  name: `Control Person ${suffix}`,
  phone: `+1-555-09${suffix.slice(0, 4)}`,
  externalReference: `crm-control-${suffix}`,
};

async function api(
  path: string, method = 'GET', body?: unknown,
  headers: Record<string, string> = {}, key: string | null = apiKey,
): Promise<{ status: number; body: any }> {
  const requestHeaders: Record<string, string> = { ...headers };
  if (key) requestHeaders.authorization = `Bearer ${key}`;
  const init: RequestInit = { method, headers: requestHeaders };
  if (body !== undefined) { requestHeaders['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const response = await fetch(`${gateway}${path}`, init);
  const text = await response.text();
  return { status: response.status, body: text ? JSON.parse(text) : null };
}

async function waitFor(description: string, condition: () => Promise<boolean>, timeoutMs = 60_000): Promise<void> {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (await condition()) return;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`timed out waiting for: ${description}`);
}

async function createCustomer(persona: typeof PII): Promise<{ id: string; paymentMethodId: string; paymentId: string }> {
  const customer = await api('/v1/customers', 'POST', { ...persona, metadata: { segment: 'erasure-e2e' } });
  assert.equal(customer.status, 201, JSON.stringify(customer.body));
  const customerId = customer.body.id as string;
  await api(`/v1/customers/${customerId}/addresses`, 'POST', {
    kind: 'billing', line1: '1 Erasure Lane', city: 'Testville', region: 'TS', postalCode: '00001', country: 'US',
  });
  await api(`/v1/customers/${customerId}/contacts`, 'POST', { kind: 'email', value: persona.email, isPrimary: true });
  const method = await api(`/v1/customers/${customerId}/payment-methods`, 'POST', {
    providerToken: `tok_erasure_${randomUUID()}`, type: 'card', brand: 'visa', last4: '4242',
    billingName: persona.name, billingAddress: { line1: '1 Erasure Lane', city: 'Testville' },
  });
  assert.equal(method.status, 201);
  await api(`/v1/customers/${customerId}/support-tickets`, 'POST', {
    subject: 'Erasure test ticket', body: `Reach me at ${persona.email} or ${persona.phone}`,
  });
  await api('/v1/customer-imports', 'POST', { source: 'erasure-e2e', record: { customerId, ...persona } });
  const invoice = await api('/v1/invoices', 'POST', {
    customerId, currency: 'USD', tax: 100, lines: [{ description: 'Erasure e2e service', quantity: 1, unitAmount: 2000 }],
  });
  assert.equal(invoice.status, 201, JSON.stringify(invoice.body));
  const payment = await api('/v1/payments', 'POST', {
    customerId, paymentMethodId: method.body.id, amount: 2100, currency: 'USD', description: `Order for ${persona.name}`,
  }, { 'idempotency-key': `erasure-e2e-pay-${randomUUID()}` });
  assert.equal(payment.status, 202, JSON.stringify(payment.body));
  return { id: customerId, paymentMethodId: method.body.id, paymentId: payment.body.id };
}

async function minioObjects(): Promise<Map<string, string>> {
  const keys: string[] = await new Promise((resolve, reject) => {
    const found: string[] = [];
    const stream = objectStore.listObjectsV2(DOCUMENT_BUCKET, '', true);
    stream.on('data', (item) => found.push(item.name));
    stream.on('error', reject);
    stream.on('end', () => resolve(found));
  });
  const objects = new Map<string, string>();
  for (const key of keys) {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, key);
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(chunk as Buffer);
    objects.set(key, Buffer.concat(chunks).toString('utf8'));
  }
  return objects;
}

// --- setup -----------------------------------------------------------------
await pool.query(
  `INSERT INTO platform.api_keys(merchant_id,key_hash,label,scopes)
   VALUES($1,$2,'restricted e2e',ARRAY['customers:read','customers:write']) ON CONFLICT(key_hash) DO NOTHING`,
  [merchantId, createHash('sha256').update(restrictedKey).digest('hex')],
);

const target = await createCustomer(PII);
const control = await createCustomer(CONTROL);
console.log('setup complete', { target: target.id, control: control.id });

await waitFor('target payment to succeed', async () => {
  const payment = await api(`/v1/payments/${target.paymentId}`);
  return payment.body?.status === 'succeeded';
});
await waitFor('projections and receipts to settle', async () => {
  const receipts = await pool.query(
    `SELECT count(*)::int c FROM operations.document_manifests WHERE document_type='receipt'
     AND metadata->>'paymentId' IN ($1,$2)`, [target.paymentId, control.paymentId]);
  return receipts.rows[0].c === 2;
});
await new Promise((resolve) => setTimeout(resolve, 3_000));

// --- negative API cases ------------------------------------------------------
assert.equal((await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'x'.repeat(12) }, null)).status, 401, 'missing auth must be 401');
assert.equal((await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'x'.repeat(12) }, restrictedKey)).status, 403, 'missing scope must be 403');
assert.equal((await api(`/v1/customers/${target.id}/erasure-requests`, 'POST')).status, 400, 'missing key must be 400');
assert.equal((await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'short' })).status, 400, 'short key must be 400');
assert.equal((await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'x'.repeat(12) })).status, 404, 'unknown customer must be 404');
assert.equal((await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'y'.repeat(12) }, otherKey)).status, 404, 'other merchant customer must be 404');
console.log('negative cases ok');

// --- request lifecycle -------------------------------------------------------
const key = `erasure-e2e-${suffix}`;
const created = await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(created.status, 202, JSON.stringify(created.body));
assert.equal(created.body.customerId, target.id);
assert.equal(created.body.status, 'pending');
assert.equal(created.body.attempts, 0);
assert.equal(created.body.completedAt, null);
assert.equal(created.body.lastError, null);
for (const field of ['id', 'createdAt', 'updatedAt']) assert.ok(created.body[field], `missing ${field}`);
const requestId = created.body.id as string;

const replay = await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(replay.status, 202);
assert.equal(replay.body.id, requestId, 'idempotent replay must return the same request');

const conflict = await api(`/v1/customers/${control.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(conflict.status, 409, 'key reuse for another customer must be 409');

const newKey = await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `other-${suffix}` });
assert.equal(newKey.status, 202);
assert.equal(newKey.body.id, requestId, 'new key for same customer must return the existing request');

