assert.equal((await api(`/v1/erasure-requests/${randomUUID()}`)).status, 404, 'unknown request must be 404');
const restrictedGet = await api(`/v1/erasure-requests/${requestId}`, 'GET', undefined, {}, restrictedKey);
assert.equal(restrictedGet.status, 200, 'customers:read key may check status');
console.log('request lifecycle ok');

await waitFor('erasure request to complete', async () => {
