assert.equal((await q(`SELECT count(*)::int c FROM operations.notification_preferences WHERE customer_id=$1`, [target.id]))[0].c, 0, 'notification preferences must be deleted');
assert.equal((await q(`SELECT count(*)::int c FROM operations.notifications WHERE customer_id=$1`, [target.id]))[0].c, 0, 'notifications must be deleted');
assert.equal((await q(`SELECT count(*)::int c FROM operations.email_deliveries WHERE customer_id=$1`, [target.id]))[0].c, 0, 'email deliveries must be deleted');
assert.equal((await q(`SELECT count(*)::int c FROM platform.audit_logs WHERE target_id=$1 AND metadata<>'{}'`, [target.id]))[0].c, 0, 'audit metadata must be scrubbed');

const sandbox = await q<{ email: string; name: string }>(`SELECT email,name FROM provider_sandbox.customers WHERE payflow_customer_id=$1`, [target.id]);
for (const row of sandbox) {
  assert.ok(!row.email.includes(PII.email) && !row.name.includes(PII.name), 'provider sandbox profile must be anonymized');
}

// broad PII scan across payload-bearing tables
const piiTerms = [PII.email, PII.name, PII.phone, PII.externalReference];
for (const table of ['operations.outbox_events', 'operations.jobs', 'operations.dead_letters']) {
  const rows = await q<{ payload: unknown }>(`SELECT payload FROM ${table}`, []);
  for (const row of rows) {
    const text = JSON.stringify(row.payload);
    for (const term of piiTerms) assert.ok(!text.includes(term), `${table} payload still contains ${term}`);
  }
}
const attempts = await q<{ request_payload: unknown }>(
  `SELECT request_payload FROM payments.payment_attempts pa JOIN payments.payment_intents pi ON pi.id=pa.payment_intent_id WHERE pi.customer_id=$1`, [target.id]);
