  for (const term of piiTerms) assert.ok(!JSON.stringify(row.request_payload).includes(term), 'payment attempt payload still contains PII');
}
console.log('database verification ok');

// --- redis / opensearch ------------------------------------------------------
const redis = new Redis(process.env.REDIS_URL!);
