assert.equal(await redis.exists(`merchant:${merchantId}:customer:${target.id}:activity`), 0, 'redis activity projection must be deleted');
assert.equal(await redis.exists(`merchant:${merchantId}:customer:${control.id}`), 1, 'control redis projection must remain');
const search = await searchClient.get({ index: CUSTOMER_INDEX, id: `${merchantId}:${control.id}` });
assert.ok(search.body.found, 'control search document must remain');
assert.ok(!JSON.stringify(search.body).includes(CONTROL.email) === false, 'control search document keeps its own data');
await assert.rejects(
  searchClient.get({ index: CUSTOMER_INDEX, id: `${merchantId}:${target.id}` }),
  (error: any) => error.meta?.statusCode === 404,
  'target search document must be deleted',
);
console.log('redis/opensearch verification ok');

// --- minio -------------------------------------------------------------------
const objects = await minioObjects();
for (const [key, content] of objects) {
  for (const term of piiTerms) assert.ok(!content.includes(term), `stored object ${key} still contains ${term}`);
}
assert.ok([...objects.keys()].some((key) => key.includes(`/receipts/${target.paymentId}`)), 'receipt object must be retained');
assert.ok([...objects.values()].some((content) => content.includes(CONTROL.email)), 'control documents must keep their data');
const manifests = (await q<{ c: number }>(`SELECT count(*)::int c FROM operations.document_manifests`, []))[0];
assert.equal(objects.size, manifests.c, 'stored objects and manifests must stay consistent');
console.log('minio verification ok');

// --- financial integrity -------------------------------------------------------
const unbalanced = (await q<{ c: number }>(`
  SELECT count(*)::int c FROM (
    SELECT e.id FROM payments.ledger_entries e JOIN payments.ledger_postings p ON p.entry_id=e.id
    GROUP BY e.id HAVING sum(CASE WHEN p.direction='debit' THEN p.amount ELSE -p.amount END)<>0
  ) invalid`, []))[0];
assert.equal(unbalanced.c, 0, 'ledger must remain balanced');
assert.equal((await q(`SELECT count(*)::int c FROM payments.captures WHERE payment_intent_id=$1 AND status='succeeded'`, [target.paymentId]))[0].c, 1, 'capture must be retained');
const runs = await q<{ status: string }>(`SELECT status FROM payments.reconciliation_runs`, []);
assert.ok(runs.every((run) => run.status === 'matched'), 'reconciliation must remain matched');
console.log('financial integrity ok');

// --- post-erasure behavior -----------------------------------------------------
assert.equal((await api(`/v1/customers/${target.id}`)).status, 404, 'erased customer must not be retrievable');
const repost = await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(repost.status, 202, 'reposting the same request must stay valid');
assert.equal(repost.body.id, requestId, 'reposting must keep the same request id');
assert.equal(repost.body.status, 'completed');
const newKeyAfter = await api(`/v1/customers/${target.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `after-${suffix}` });
assert.equal(newKeyAfter.body.id, requestId, 'new key after completion returns the existing request');
const blockedPayment = await api('/v1/payments', 'POST', {
