}, { 'idempotency-key': `blocked-${randomUUID()}` });
assert.ok([409, 422].includes(blockedPayment.status), `payment for erased customer must be rejected, got ${blockedPayment.status}`);
const controlPayment = await api(`/v1/payments/${control.paymentId}`);
assert.equal(controlPayment.body.status, 'succeeded', 'control payment must be unaffected');
const controlCustomer = await api(`/v1/customers/${control.id}`);
assert.equal(controlCustomer.body.email, CONTROL.email, 'control customer must be unaffected');
console.log('post-erasure behavior ok');

console.log('ALL ERASURE E2E CHECKS PASSED');
await redis.quit();
await pool.end();
