const suffix = randomUUID().slice(0, 8);
const PII = {
  email: `late-${suffix}@example.test`, name: `Late Callback ${suffix}`,
  phone: `+1-555-07${suffix.slice(0, 4)}`, externalReference: `crm-late-${suffix}`,
