async function api(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}) {
  const requestHeaders: Record<string, string> = { authorization: `Bearer ${apiKey}`, ...headers };
  const init: RequestInit = { method, headers: requestHeaders };
  if (body !== undefined) { requestHeaders['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const response = await fetch(`${gateway}${path}`, init);
