{"command":"create","path":"/workspace/source/scripts/tmp-erasure-retry.ts","file_text":"/* Temporary test: failed requests expose stable codes and are safe to retry. Deleted after use. */
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { pool } from '../packages/database/src/pool.js';

const gateway = process.env.GATEWAY_URL ?? 'http://api-gateway:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';
const suffix = randomUUID().slice(0, 8);
const PII = { email: `retry-${suffix}@example.test`, name: `Retry Person ${suffix}`, externalReference: `crm-retry-${suffix}` };

async function api(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}) {
  const requestHeaders: Record<string, string> = { authorization: `Bearer ${apiKey}`, ...headers };
  const init: RequestInit = { method, headers: requestHeaders };
  if (body !== undefined) { requestHeaders['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const response = await fetch(`${gateway}${path}`, init);
  return { status: response.status, body: await response.json().catch(() => null) };
}

async function waitFor(description: string, condition: () => Promise<boolean>, timeoutMs = 90_000): Promise<void> {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (await condition()) return;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`timed out waiting for: ${description}`);
}

// OpenSearch is stopped by the caller, so the first cleanup attempt must fail.
const customer = await api('/v1/customers', 'POST', { ...PII, metadata: {} });
const customerId = customer.body.id as string;
const key = `retry-erase-${suffix}`;
const created = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(created.status, 202);
const requestId = created.body.id as string;

await waitFor('request to fail with a stable error code', async () => {
  const status = await api(`/v1/erasure-requests/${requestId}`);
  return status.body?.status === 'failed';
});
const failed = await api(`/v1/erasure-requests/${requestId}`);
assert.equal(failed.body.status, 'failed');
assert.match(failed.body.lastError, /^[a-z_]+$/, 'lastError must be a stable code');
assert.ok(!failed.body.lastError.includes(PII.email) && !failed.body.lastError.includes(customerId), 'lastError must not contain customer data');
assert.equal(failed.body.completedAt, null);
console.log('failed with stable code:', failed.body.lastError);

// Reposting the same request requeues it, keeping the same id.
const repost = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(repost.status, 202);
assert.equal(repost.body.id, requestId, 'retry must keep the same request id');
assert.equal(repost.body.status, 'pending', 'reposted failed request must be requeued');
console.log('RESUME_OPENSEARCH');

await waitFor('requeued request to complete', async () => {
  const status = await api(`/v1/erasure-requests/${requestId}`);
  return status.body?.status === 'completed';
});
const done = await api(`/v1/erasure-requests/${requestId}`);
assert.equal(done.body.status, 'completed');
assert.equal(done.body.lastError, null);
assert.ok(done.body.completedAt);
assert.ok(done.body.attempts >= 2, 'attempts must reflect the retry');
assert.equal((await pool.query(`SELECT count(*)::int c FROM customers.customers WHERE id=$1`, [customerId])).rows[0].c, 0);
console.log('retry converged to completed');

// Simulate a worker crash mid-attempt: a stale processing row must be recovered and rerun.
await pool.query(
  `UPDATE customers.erasure_requests SET status='processing',updated_at=now()-interval '10 minutes' WHERE id=$1`,
  [requestId],
);
await waitFor('stale processing request to be recovered and completed', async () => {
  const status = await api(`/v1/erasure-requests/${requestId}`);
  return status.body?.status === 'completed';
}, 120_000);
console.log('stale processing recovery ok');

console.log('RETRY/RECOVERY TEST PASSED');
await pool.end();
"}

